# Sections supplémentaires pour rallonger les articles existants (environ x2).
from wiki_content import RN
P = lambda *xs: ''.join(f'<p>{x}</p>' for x in xs)
UL = lambda *xs: '<ul>' + ''.join(f'<li>{x}</li>' for x in xs) + '</ul>'

EXT = {
# ---------- ce que j’aime ----------
'code': [('Pourquoi c’est addictif', P('Le code, c’est un jeu où l’on invente les règles. On a une idée, on l’écrit, et quelques minutes plus tard elle existe à l’écran. Peu de choses donnent ce sentiment de pouvoir aussi vite.', 'Et quand ça ne marche pas, c’est une énigme. Trouver le bug, c’est comme gagner une partie serrée.')),
         ('Les langages de Wyatt', UL('Python, le premier, avec la tortue.', 'JavaScript, pour tout ce qui bouge sur le web.', 'HTML et CSS, pour la structure et le style.', 'Luau, pour les jeux Roblox.') + P('Et un nombre de points-virgules vérifiés que la science ne sait pas encore mesurer ' + RN + '.'))],
'python': [('Pourquoi on l’apprend en premier', P('Python a une syntaxe très propre : pas d’accolades partout, juste des retraits pour montrer ce qui va ensemble. On se concentre sur la logique, pas sur la ponctuation.', 'C’est pour ça qu’on le retrouve souvent au collège et au lycée, notamment en SNT et en NSI.')),
           ('Ce qu’on peut faire avec', UL('Des dessins et des petits jeux, avec turtle.', 'Des scripts qui automatisent des tâches pénibles.', 'De l’analyse de données et de l’intelligence artificielle.', 'Des générateurs de sites, comme celui de Wyattpédia.') + P('Oui : l’encyclopédie que tu lis est fabriquée par un script Python. La tortue serait fière.'))],
'javascript': [('Le langage partout', P('JavaScript est le seul langage que tous les navigateurs comprennent sans rien installer. Avec Node.js, il tourne aussi sur les serveurs. Un même langage peut donc faire un site, un serveur et un bot Discord.')),
               ('Les bizarreries célèbres', P('JavaScript a quelques surprises : <code>NaN</code> n’est pas égal à lui-même, <code>typeof null</code> renvoie « object », et <code>"2" + 2</code> donne <code>"22"</code>. Les développeurs l’aiment quand même. Enfin, la plupart du temps ' + RN + '.'))],
'sites-saas': [('Ce qui fait un bon site', UL('Il charge vite, même sur un vieux téléphone.', 'On comprend en trois secondes à quoi il sert.', 'Il marche sur tous les écrans.', 'Il respecte la vie privée des visiteurs.') + P('Le reste, c’est du bonus. Le motion design, par exemple. Beaucoup de bonus, chez Wyatt.')),
               ('Le rêve SaaS', P('Un SaaS réussi, c’est un outil que des gens utilisent tous les jours et qui leur fait gagner du temps. Le bot des impôts en est un petit avant-goût : un service en ligne, utilisé par toute une communauté.', 'Prochaine étape : un vrai SaaS, avec des comptes, des abonnements et des clients. Ce jour-là, Wyattpédia aura un nouvel article.'))],
'hacking-ethique': [('Comment se passe une recherche', UL('Lire les règles du programme : ce qu’on a le droit de tester, et ce qui est interdit.', 'Explorer le site comme un visiteur curieux.', 'Repérer un comportement anormal.', 'Le prouver sans abîmer quoi que ce soit.', 'Écrire un rapport clair pour que l’entreprise corrige.') + P('Le rapport compte autant que la faille. Une faille mal expliquée ne sert à rien.')),
                    ('Les failles classiques', P('Parmi les plus connues : les failles XSS, où l’on injecte du JavaScript dans une page, et les injections SQL, où l’on parle directement à la base de données. Chacune a son article dans Wyattpédia.', 'Le hacking éthique est aussi une excellente porte d’entrée vers les métiers de la cybersécurité. Et vers le plan B de Wyatt.'))],
'bots-discord': [('Ce qu’un bot sait faire', UL('Répondre à des commandes slash.', 'Donner ou retirer des rôles.', 'Envoyer des messages privés ou des rappels.', 'Gérer des candidatures, des tickets, des économies de jeu.') + P('En gros, tout ce qui est répétitif et que les modérateurs n’ont pas envie de faire à la main.')),
                 ('Comment on en crée un', P('On déclare une application sur le portail développeur de Discord, on récupère un jeton secret, puis on écrit le code, souvent avec discord.js ou une bibliothèque Python. Le jeton ne doit jamais être partagé : c’est la clé du bot.'))],
'claude-maxxing': [('Une journée type', UL('Expliquer à Claude ce qu’on veut construire.', 'Lire ce qu’il propose, et poser des questions.', 'Tester, casser, recommencer.', 'Comprendre chaque ligne avant de la garder.') + P('Le but n’est pas de faire coder l’IA à sa place. C’est d’aller plus vite, et d’apprendre en chemin.')),
                   ('Les limites', P('Une IA peut se tromper avec beaucoup d’assurance. Elle peut inventer une fonction qui n’existe pas, ou oublier un cas particulier. D’où la règle : on vérifie tout. Surtout ce qui touche à la sécurité et au juridique.'))],
'vs-code': [('Les extensions', P('La force de VS Code, ce sont ses extensions : coloration pour chaque langage, mise en forme automatique, aperçu des pages en direct, intégration de Git. On construit son propre outil, pièce par pièce.')),
            ('Les raccourcis qui changent la vie', UL('<code>Ctrl + P</code> : ouvrir un fichier en tapant son nom.', '<code>Ctrl + Shift + P</code> : chercher n’importe quelle commande.', '<code>Alt + clic</code> : écrire à plusieurs endroits en même temps.', '<code>Ctrl + /</code> : mettre une ligne en commentaire.') + P('Utiliser la souris, c’est perdre une seconde. Sur une nuit blanche, ça fait beaucoup de secondes ' + RN + '.'))],
'github': [('Ce qu’on y trouve', UL('Des dépôts : un dossier par projet, avec tout son historique.', 'Des « issues » pour noter les bugs et les idées.', 'Des « pull requests » pour proposer et relire des changements.', 'GitHub Pages, pour publier un site gratuitement.')),
           ('Le portfolio des développeurs', P('Pour un développeur, un profil GitHub joue un peu le rôle d’un CV. On y voit ses projets, son activité et sa façon de coder. Garder ses dépôts propres et bien décrits, c’est déjà se présenter.'))],
'discord': [('Les serveurs RP', P('Sur un serveur de jeu de rôle, Discord sert de mairie, de poste de police et de bureau des impôts. On y dépose sa candidature, on reçoit son rôle, on suit les annonces. Le jeu se passe sur GTA, mais l’organisation vit sur Discord.')),
            ('Bonnes pratiques', P('Ne jamais partager le jeton d’un bot. Activer la double authentification sur son compte. Se méfier des liens « Nitro gratuit ». Discord est un endroit génial, mais aussi une cible pour les arnaques.'))],
'phonk': [('Les ingrédients', UL('Une cloche (« cowbell ») qui revient en boucle.', 'Des basses énormes, qui saturent un peu.', 'Des voix découpées et ralenties.', 'Un tempo qui donne envie d’accélérer.') + P('Le « drift phonk », très populaire en ligne, pousse tout ça encore plus loin. Parfait pour les vidéos de voitures. Et pour les sessions de code.')),
          ('Pourquoi ça marche pour coder', P('Une musique répétitive et sans paroles compréhensibles aide certaines personnes à se concentrer. Le cerveau a un rythme à suivre, et rien qui le distrait. Le volume, lui, reste un débat ' + RN + '.'))],
'gta-vi': [('Ce qui change', P('GTA VI revient à Vice City, la ville inspirée de Miami, avec une carte plus grande et plus vivante. Le jeu suit un duo de personnages, Lucia et Jason. Il a été l’un des jeux les plus attendus de l’histoire du jeu vidéo.')),
           ('GTA V, le grand frère', P('GTA V est sorti en 2013 et a été joué pendant plus de dix ans, notamment grâce à GTA Online et aux serveurs RP. C’est là que Wyatt a vécu des années de souvenirs. D’où la petite nostalgie, même devant le nouveau.'))],
'gta-rp': [('Les règles du RP', UL('Rester dans son personnage, même quand ça tourne mal.', 'Ne pas utiliser d’informations du monde réel dans le jeu.', 'Respecter les autres joueurs et leur histoire.', 'Jouer la peur, la douleur, les conséquences.') + P('Ce n’est pas « gagner » qui compte : c’est raconter une bonne histoire, ensemble.')),
           ('Un vrai terrain d’entraînement', P('Gérer une entreprise fictive, recruter, négocier, écrire un dossier : le RP fait travailler des compétences bien réelles. Le dossier Linear, avec ses 17 plans en motion design, en est la preuve.'))],
'black-ops-6': [('L’histoire', P('La campagne se passe au début des années 1990, au moment de la guerre du Golfe. On y retrouve l’ambiance d’espionnage de la série : agents doubles, trahisons, missions secrètes.')),
                ('Pourquoi la campagne', P('Wyatt préfère la campagne au multijoueur classique : une histoire écrite, des personnages, une mise en scène. Un peu comme un film qu’on joue. Et ça laisse plus de temps pour coder qu’une soirée de classées ' + RN + '.'))],
'warzone': [('Comment se passe une partie', UL('Atterrir en parachute sur une grande carte.', 'Chercher des armes et de l’équipement.', 'Survivre pendant que la zone se resserre.', 'Être le dernier debout. En théorie.')),
            ('Le Goulag', P('Dans Warzone, un joueur éliminé peut avoir une seconde chance au « Goulag », un duel pour revenir dans la partie. Un système de seconde chance que Wyatt aimerait bien appliquer à ses bugs en production.'))],
'tiktok': [('Les types de vidéos', UL('Des parodies, comme la fameuse Ariana Grande.', 'Des edits, montés sur de la musique.', 'De l’humour, beaucoup d’humour.') + P('Le compte s’appelle @siroxletag. L’ancien, @siroxtag, a été banni : un épisode dont on ne parle pas trop ' + RN + '.')),
           ('Ce que TikTok apprend', P('Faire une vidéo courte, c’est apprendre à capter l’attention en une seconde, à raconter vite et à couper tout ce qui ne sert pas. Exactement les mêmes règles qu’une bonne page web.'))],
'nuit-blanche': [('Ce que dit la science', P('Après une nuit sans sommeil, la concentration et les réflexes baissent nettement. Après plusieurs, l’humeur, la mémoire et la santé en prennent un coup. Le cerveau a besoin de dormir pour trier et ranger ce qu’il a appris.')),
                 ('La version raisonnable', UL('Fixer une heure de fin, même approximative.', 'Noter l’idée pour demain au lieu de tout coder tout de suite.', 'Se rappeler que le bug sera toujours là au réveil. Et souvent plus facile à trouver.') + P('Wyattpédia rappelle que dormir est aussi une compétence de développeur.'))],
'manger-en-codant': [('Les risques du métier', UL('Les miettes dans le clavier.', 'Le verre renversé sur l’ordinateur portable.', 'Les doigts gras sur l’écran.', 'L’assiette oubliée à côté pendant trois heures.')), ('Conseil d’ami', P('Une pause repas, même courte, aide à prendre du recul. Beaucoup de bugs se résolvent tout seuls entre deux bouchées, loin de l’écran. Le canard en caoutchouc approuve.'))],
'bug': [('Comment on s’en sort', UL('Vider tous les caches, partout.', 'Comparer la page envoyée par le serveur et celle du navigateur.', 'Chercher ce qui change entre les deux : une date, une valeur aléatoire, un réglage.', 'Ajouter des messages pour rendre l’erreur visible.') + P('Le plus dur n’est pas de corriger. C’est de comprendre qu’il y a un problème.')),
        ('La leçon', P('Un bug qui ne fait pas planter est souvent plus dangereux qu’un bug qui plante. Depuis, Wyatt teste ses sites en navigation privée, sur plusieurs appareils, et se méfie de tout ce qui « marche sur sa machine ».'))],
'policier': [('Les différentes voies', UL('Gardien de la paix : le policier de terrain, recruté sur concours.', 'Policier adjoint : une porte d’entrée accessible sans diplôme, pour découvrir le métier.', 'Cadets de la République : un dispositif pour préparer le concours.', 'Officier, commissaire : des concours de plus haut niveau.') + P('Les conditions exactes sont sur le site officiel du recrutement de la Police nationale.')),
             ('Les qualités demandées', P('Le sens du service, le sang-froid, la condition physique et l’honnêteté. Le métier demande aussi de savoir écouter et rédiger : un bon rapport d’intervention compte beaucoup. Un peu comme un bon rapport de bug.'))],
'cyberpolicier': [('Les menaces du quotidien', UL('L’hameçonnage : les faux messages qui volent des mots de passe.', 'Les rançongiciels, qui bloquent des ordinateurs contre de l’argent.', 'Les arnaques en ligne et les faux vendeurs.', 'Le cyberharcèlement.') + P('Chacune a son article dans la partie « Police et cyber » de Wyattpédia.')),
                  ('Les compétences utiles', P('Comprendre les réseaux, savoir analyser des traces numériques, connaître la loi et rédiger des procédures. Les compétitions de type CTF et le bug bounty sont de très bons entraînements. Wyatt en a déjà un bout.'))],
'developpeur': [('Les spécialités', UL('Front-end : ce que l’on voit.', 'Back-end : ce qui tourne en coulisses.', 'Full-stack : un peu des deux.', 'Jeu vidéo, mobile, data, sécurité…') + P('Wyatt touche déjà au front, au back et au jeu vidéo. Le full-stack lui tend les bras.')),
                ('Comment on y arrive', P('Il existe de nombreux chemins : BUT informatique, BTS SIO, licence, école d’ingénieur, alternance, ou même en autodidacte avec un bon portfolio. Le plus important reste de construire des projets. Ça tombe bien, Wyatt ne fait que ça.'))],
'filiere-generale': [('Le programme commun', P('En seconde, tout le monde suit les mêmes matières, dont SNT (Sciences numériques et technologie), un premier contact avec l’informatique. Il y a aussi les maths, le français, l’histoire-géo, les langues et les sciences.')),
                     ('Le combo idéal pour Wyatt', P('Pour garder ouverts les plans A, B et C, une combinaison comme NSI et maths a beaucoup de sens. NSI pour le code, les maths pour la logique. Les spécialités se choisissent avec les professeurs et la famille, en fonction des envies et des projets.'))],
# ---------- projets ----------
'siroxtag-fr': [('La sécurité juridique', P('Le site a des mentions légales complètes : éditeur, hébergeur, marques citées, cookies, données. Il précise aussi que les jeux de rôle sont de la fiction et que l’humour est assumé. « Protège-moi du juridique de partout », avait demandé Wyatt.')),
                ('Les chiffres', UL('Zéro framework.', 'Zéro cookie publicitaire.', 'Des polices hébergées sur le site, sans appel à Google.', 'Un terminal secret.'))],
'page-perso': [('Le style', P('Fond clair, couleurs douces, typographie façon Apple. Pas de néon, pas de boutons arrondis en pilule : Wyatt voulait un style sobre, qui ne fasse pas « généré à la va-vite ». L’humour, lui, est partout.')),
               ('Ce qui est caché', UL('Le mot <code>fun</code>, à taper n’importe où.', 'Le code Konami.', 'Les commandes <code>wiki</code> et <code>hasard</code> du terminal.', 'La photo qui fait coucou quand on la survole.'))],
'wyattpedia': [('Les chiffres', P('Des dizaines d’articles, des centaines de liens entre eux, et une recherche instantanée. Chaque article a un sommaire, une fiche résumé, des liens « Voir aussi » et des références. Certaines sont sérieuses, d’autres beaucoup moins.')),
               ('Comment ajouter un article', P('Il suffit d’ajouter une entrée dans le fichier de contenu, puis de relancer le script. Le générateur crée la page, l’ajoute au sommaire, à la recherche et au bouton « Article au hasard », et place les liens automatiquement.'))],
'blackout': [('L’ambiance', P('Le noir complet, des bruits qu’on n’identifie pas, et la peur de se retrouver seul. Le jeu mise sur la coopération : à plusieurs, on se rassure. Jusqu’à ce que la lumière s’éteigne.')),
             ('Ce que ça apprend', P('Créer un jeu, c’est tout gérer : le scénario, les niveaux, les sons, le code, et les tests avec de vrais joueurs. C’est sans doute le projet le plus complet de Wyatt.'))],
'linear': [('Pourquoi en motion design', P('Un dossier classique, c’est un PDF qu’on survole. Un dossier en motion design, c’est un petit film qu’on regarde jusqu’au bout. Pour présenter une entreprise de jeu de rôle, l’effet est garanti.')),
           ('Les versions', P('Une version paysage pour ordinateur, une version portrait pour téléphone. Les textes ont été réécrits pour sonner naturels, et le noir et blanc donne un style sobre, presque cinéma.'))],
'bot-impots': [('Les commandes admin', UL('Créer un code promo à usage unique, avec un pourcentage et une durée.', 'Révoquer un code avant qu’il serve.', 'Ajouter ou retirer un montant à un membre.', 'Voir la liste de ce que chacun doit.') + P('Les commandes admin sont masquées aux autres membres. Le fisc a ses secrets.')),
               ('Ce que ça apprend', P('Gérer des données, des droits d’accès, des cas particuliers (un couple dont un seul a accepté, un code expiré…). Un vrai petit logiciel, avec de vrais utilisateurs. Et de vraies réclamations ' + RN + '.'))],
'terminal-cache': [('Comment il est fait', P('Une fenêtre en HTML et CSS, un champ de saisie, et un dictionnaire de commandes en JavaScript. Chaque commande a une description et une fonction. Un historique permet de rappeler les commandes avec les flèches du clavier.')),
                   ('Pourquoi un terminal', P('Parce que c’est l’outil préféré des développeurs, et que ça rend le site vivant. Le visiteur curieux est récompensé. Et ça fait un excellent sujet de conversation ' + RN + '.'))],
}
